//! Host bindings of the `rustman:plugin@1.0.0` WIT package, generated by
//! wasmtime: one module for the host imports, and one per extension point
//! world, which reuse the host imports' types.

/// The host imports every plugin links against.
pub mod host {
    wasmtime::component::bindgen!({
        path: "../rustman-plugin-sdk/wit",
        world: "rustman:plugin/host",
        additional_derives: [PartialEq, Eq],
        with: {
            "rustman:plugin/secrets.secret-ref": crate::sandbox::secrets::SecretHandle,
        },
    });
}

macro_rules! world {
    ($module:ident, $world:literal) => {
        pub mod $module {
            wasmtime::component::bindgen!({
                path: "../rustman-plugin-sdk/wit",
                world: $world,
                additional_derives: [PartialEq, Eq],
                with: {
                    "rustman:plugin/types": super::host::rustman::plugin::types,
                    "rustman:plugin/http": super::host::rustman::plugin::http,
                    "rustman:plugin/clock": super::host::rustman::plugin::clock,
                    "rustman:plugin/random": super::host::rustman::plugin::random,
                    "rustman:plugin/env": super::host::rustman::plugin::env,
                    "rustman:plugin/fs-read": super::host::rustman::plugin::fs_read,
                    "rustman:plugin/secrets": super::host::rustman::plugin::secrets,
                    "rustman:plugin/log": super::host::rustman::plugin::log,
                },
            });
        }
    };
}

world!(auth, "rustman:plugin/auth");
world!(assertion, "rustman:plugin/assertion");
world!(generator, "rustman:plugin/generator");
world!(transformer, "rustman:plugin/transformer");
world!(importer, "rustman:plugin/importer");
world!(kind, "rustman:plugin/kind");
world!(report, "rustman:plugin/report");
